system.easyEffects:
[On Clash RESULT]
create dialog "Give [Type] Protection: which type of Protection?":
  slash as "Slash Protection",
  pierce as "Pierce Protection",
  blunt as "Blunt Protection"
  to self;

[On Dialog Answer slash]
proc "Give Ally: (N*2) Slash Protection next round";

[On Dialog Answer pierce]
proc "Give Ally: (N*2) Pierce Protection next round";

[On Dialog Answer blunt]
proc "Give Ally: (N*2) Blunt Protection next round";
